  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-application, traceparent'
};
// Cadeia de fallback p/ o match da requisição manual. Tarefa = extração estruturada
// simples → priorizamos modelos baratos+rápidos+bons em seguir instrução/JSON.
// Variantes PAGAS (não :free) por confiabilidade — uma requisição custa frações de centavo.
// Dispara o próximo em erro/JSON inválido/resposta vazia.
const FALLBACK_MODELS = [
  'openai/gpt-4.1-mini',        // primário: comprovadamente confiável p/ JSON estrito desta tarefa, barato ($0.40/$1.60)
  'google/gemini-2.5-flash',    // fallback rápido, forte em extração
  'deepseek/deepseek-v4-flash', // fallback baratíssimo ($0.09/$0.18)
  'qwen/qwen3-32b'              // fallback mais barato, suporta structured output
];

function isGrokModel(model: string): boolean {
  return /(^|\/)grok/i.test(model);
}

function logEvent(level: 'info' | 'warning' | 'error', event: string, data: Record<string, unknown> = {}) {
  const payload = { ts: new Date().toISOString(), function: 'process-requisition-ai', event, ...data };
  if (level === 'error') console.error('[AI]', JSON.stringify(payload));
  else if (level === 'warning') console.warn('[AI]', JSON.stringify(payload));
  else console.log('[AI]', JSON.stringify(payload));
}

// ─── Reparo determinístico do nome (defesa contra inconsistência do LLM) ──────
// O modelo às vezes dropa o cabeçalho da seção e devolve só o sabor ("chocolate"
// sob "Bolos no Pote"), o que faz o match ancorar em qualquer produto com a
// palavra no nome ("Mini de Chocolate"). Aqui garantimos o prefixo canônico da
// categoria, de forma idempotente. Espelha a tabela da REGRA #1 do system prompt.
const CATEGORY_PREFIX_MAP: { match: RegExp; prefix: string; standalone?: boolean }[] = [
  { match: /bolo(s)?\s+(no\s+)?pote|bolo\s+pote/, prefix: 'Bolo no Pote' },
  { match: /doce(s|inhos)?\s+(no\s+)?pote|docinhos?\s+no\s+pote/, prefix: 'Doce no Pote' },
  { match: /bombom|bombons|bombon(s)?/, prefix: 'Bombom' },
  { match: /brownie\s+low\s*carb|brownie\s+low/, prefix: 'Brownie Low Carb', standalone: true },
  { match: /docinho(s)?/, prefix: 'Docinho' },
  { match: /tartelete(s)?/, prefix: 'Tartelete' },
  { match: /fatia(s)?/, prefix: 'Fatia' },
  { match: /gelato(s)?|sorvete(s)?|\bcuba(s)?\b/, prefix: 'Cuba' },
  { match: /granola(s)?/, prefix: 'Granola' },
  { match: /caseirinho(s)?/, prefix: 'Mini Caseirinho' },
  { match: /mini(s)?/, prefix: 'Mini' },
  { match: /caf[eé]/, prefix: 'Café' },
  { match: /gingerbread/, prefix: 'Gingerbread', standalone: true },
  { match: /pronta\s+entrega/, prefix: '', standalone: true },
];

function deburrLower(s: string): string {
  return (s || '').normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase().trim();
}

/**
 * Garante que `name` carregue o prefixo canônico da categoria. Se o nome já
 * contém o prefixo (ou a categoria é standalone / desconhecida), retorna como
 * está; senão, prefixa "Prefixo Sabor". Idempotente e conservador.
 */
function repairItemName(name: string, category: string): string {
  const rawName = String(name || '').trim();
  const cat = deburrLower(category);
  if (!rawName || !cat) return rawName;
  const entry = CATEGORY_PREFIX_MAP.find((e) => e.match.test(cat));
  if (!entry || entry.standalone || !entry.prefix) return rawName;
  const prefixNorm = deburrLower(entry.prefix);
  const nameNorm = deburrLower(rawName);
  if (nameNorm.includes(prefixNorm)) return rawName; // já tem o prefixo
  return `${entry.prefix} ${rawName}`;
}

const SYSTEM_PROMPT = `# MOMMA REQUISITION PARSER — MOTOR DE EXTRAÇÃO DE PRODUTOS

Você é um sistema de extração de elite para a **MOMMA**, marca artesanal brasileira de bolos, gelatos, docinhos e outros produtos confeitados.

Sua saída aciona pedidos reais de estoque. **Erro = produto errado entregue.**

---

## ⚡ REGRA #1 — HERANÇA DE CONTEXTO DE CATEGORIA (MAIS CRÍTICA)

As mensagens usam formato hierárquico: um **cabeçalho de categoria** seguido de **sub-itens** (apenas sabor/variante).

O campo \`name\` DEVE ser o nome COMPLETO do produto = prefixo canônico da categoria + sabor/variante.
**NUNCA** escreva apenas o sabor quando houver um cabeçalho de categoria acima.

### Mapeamento de Categorias → Prefixos Canônicos

| Variantes do cabeçalho (case-insensitive) | Prefixo canônico | Exemplo de nome completo |
|---|---|---|
| Bolos no pote / Bolo no pote / bolo pote | "Bolo no Pote" | "Bolo no Pote Banoffee" |
| Bombons / Bombom | "Bombom" | "Bombom Morango" |
| Brownie lowcarb / Brownie low carb / brownie low | "Brownie Low Carb" | "Brownie Low Carb" |
| Doces no Pote / Doce no pote / docinhos no pote | "Doce no Pote" | "Doce no Pote Doce de Leite" |
| Docinho / Docinhos / docinho bolinha | "Docinho" | "Docinho Misto" |
| Caseirinho / Caseirinhos | "Mini Caseirinho" | "Mini Caseirinho Milho" |
| Mini / Minis | "Mini" | "Mini Ferrero Rocher" |
| Tartelete / Tarteletes | "Tartelete" | "Tartelete Chocomelo" |
| Fatias / Fatia | "Fatia" | "Fatia Chocomelo" |
| Gelatos / Gelato / Cubas / Cuba | "Cuba" | "Cuba Pistache" |
| Granolas / Granola | "Granola" | "Granola Baunilha" |
| Café | "Café" | "Café em Grão" |
| Gingerbread | standalone — sem prefixo | "Gingerbread" |
| Pronta entrega | standalone — sem prefixo | "Vulcão de Pistache" |

**Regra de escopo:** o cabeçalho permanece ativo até o próximo cabeçalho ou até o fim do texto.

---

## REGRA #2 — SE CATÁLOGO FORNECIDO, USE OS NOMES EXATOS

Se houver uma seção \`[CATÁLOGO DE PRODUTOS]\` no input, cada item extraído DEVE ser mapeado ao nome mais próximo do catálogo. O catálogo é a fonte verdade. Prefira o nome exato do catálogo ao invés do nome reconstituído.

Estratégia:
1. Identificar sabor/variante do texto + prefixo da categoria
2. Buscar no catálogo o produto que melhor corresponde
3. Usar exatamente esse nome no campo \`name\`

---

## REGRA #3 — ZERO ALUCINAÇÃO

- Não invente produtos que não estão no texto
- Não estime quantidades — sem número = 1
- Não adicione itens "que geralmente vêm junto"
- Se ambíguo, registre na \`observation\`

---

## REGRA #4 — PARSING DE QUANTIDADES

| Formato | Resultado |
|---|---|
| "3 caixas" / "3cx" / "3 - cx" / "3- cx" | requested=3, observation="caixas" |
| "9 UND" / "9 unidades" | requested=9, observation="UND" |
| "1 saco" | requested=1, observation="saco" |
| "2 - cx" (traço antes de cx) | requested=2, observation="caixas" |
| "1k" / "1 kg" | requested=1, observation="1kg" |
| apenas número | requested=número |
| sem número | requested=1 |

---

## REGRA #5 — LIMPEZA DE RUÍDO

Remova do texto antes de processar:
- Timestamps: \`[10:01, 13/03/2026] Breno:\`
- Cabeçalhos de requisição: "Requisição 13/03:", "Requisição do dia X"
- Emojis, marcadores (*, -, •, números com ponto)
- Saudações: "bom dia", "segue lista", "olá"

---

## ⚡ REGRA #6 — SOURCE_TEXT (RASTREABILIDADE — OBRIGATÓRIO)

Cada item DEVE conter o campo \`source_text\`: o trecho **verbatim** do input do usuário que originou aquele item — exatamente como foi digitado, **antes** de você reconstruir o nome canônico.

- É a evidência que o humano usa para conferir se o match veio certo. Copie literal do input: NÃO normalize, NÃO corrija ortografia, NÃO traduza, NÃO adicione o prefixo de categoria.
- Inclua o sabor/variante e o token de quantidade como apareceram (ex.: "banoffe: 3 caixas").
- Ex.: input "banoffe: 3 caixas" sob cabeçalho "Bolos no pote" → \`name\`="Bolo no Pote Banoffee", \`source_text\`="banoffe: 3 caixas".
- OBRIGATÓRIO em TODOS os itens (mesmo que os Exemplos 2 e 3 abaixo, por brevidade, nem sempre o repitam).

---

## FORMATO DE SAÍDA (JSON V2 ESTRITO)

\`\`\`json
{
  "schema_version": "2",
  "categories": [
    {
      "category": "nome_da_categoria",
      "items": [
        { "name": "Nome Completo Produto", "source_text": "trecho verbatim do input que gerou este item", "requested": 1, "sent": null, "observation": "opcional" }
      ]
    }
  ],
  "meta": { "total_items": N, "total_requested": N },
  "_debug_verification": "Categorias: X. Itens: Y. Prefixos aplicados: Z. Catálogo usado: sim/não."
}
\`\`\`

