// Função para retry com backoff exponencial
async function retryWithBackoff(fn, maxRetries = 3, baseDelay = 1000) {
  let lastError;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      // Se é o último attempt, lança o erro
      if (attempt === maxRetries) {
        throw lastError;
      }
      // Calcular delay com backoff exponencial
      const delay = baseDelay * Math.pow(2, attempt);
      console.log(`❌ Tentativa ${attempt + 1} falhou: ${lastError.message}. Tentando novamente em ${delay}ms...`);
      // Aguardar antes da próxima tentativa
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}
// Função para fazer requisições à API do OpenRouter com fallback de modelo
async function makeOpenRouterRequestWithModel(prompt, model) {
  const apiKey = Deno.env.get('OPENROUTER_API_KEY');
  if (!apiKey) {
    throw new Error('OPENROUTER_API_KEY not set');
  }
  const fetchStart = Date.now();
  const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
      'X-Title': 'momma-manual'
    },
    body: JSON.stringify({
      model: model,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: prompt }
      ],
      temperature: 0.1,
      response_format: { type: 'json_object' }
    })
  });
  if (!response.ok) {
    const errorText = await response.text().catch(() => 'Erro desconhecido');
    console.error(`❌ OpenRouter API error with model ${model}: ${response.status} - ${errorText}`);
    logEvent('warning', 'fallback_api_error', { model, status: response.status, errorText });
    // Diferentes tipos de erro
    if (response.status === 502) {
      throw new Error(`OpenRouter API temporariamente indisponível (502 Bad Gateway). Tentando novamente...`);
    } else if (response.status === 503) {
      throw new Error(`OpenRouter API sobrecarregada (503 Service Unavailable). Tentando novamente...`);
    } else if (response.status === 429) {
      throw new Error(`Rate limit atingido (429 Too Many Requests). Tentando novamente...`);
    } else if (response.status >= 500) {
      throw new Error(`Erro interno do servidor OpenRouter (${response.status}). Tentando novamente...`);
    } else {
      // Erros 4xx não devem ser retentados
      throw new Error(`OpenRouter API error: ${response.status} - ${errorText}`);
    }
  }
  const data = await response.json();
  const durationMs = Date.now() - fetchStart;
  return { data, durationMs, model };
}
// Função para fazer requisições à API do OpenRouter com retry e fallback de modelo
// Returns { data, durationMs, model } from makeOpenRouterRequestWithModel
async function makeOpenRouterRequest(prompt) {
  let lastError;
  for (const model of FALLBACK_MODELS) {
    try {

      const res = await retryWithBackoff(async () => {
        return await makeOpenRouterRequestWithModel(prompt, model);
      }, 3, 2000);
      return res;
    } catch (err) {
      lastError = err;
      logEvent('warning', 'fallback_model_fail', { model, error: err instanceof Error ? err.message : String(err) });
      continue;
    }
  }
  throw lastError || new Error('Todos os modelos de fallback falharam');
}
// Streaming de raciocínio via SSE com fallback de modelo
async function streamOpenRouterReasoning(prompt, models, tracer?: EdgeTracer, metrics?: EdgeMetrics) {
  const encoder = new TextEncoder();
  let chosenModelIndex = -1;
  let contentBuffer = '';
  let reasoningBuffer = '';
  let normalizedReasoningSent = '';
  let seenTextDelta = false;
  let modelAnnounced = false;
  const stream = new ReadableStream({
    async start(controller) {
      // Helper para enviar evento SSE
      const sendEvent = (event, data) => {
        const payload = `event: ${event}\n` + `data: ${JSON.stringify(data)}\n\n`;
        controller.enqueue(encoder.encode(payload));
      };
      sendEvent('status', { message: 'Processando IA...' });
      // Keepalive: evita que browser/proxy encerre SSE por inatividade enquanto o modelo processa
      const keepaliveTimer = setInterval(() => {
        try { sendEvent('status', { message: 'Aguardando IA...', heartbeat: true }); } catch (_) {}
      }, 20000);
      // Tenta modelos em sequência
      for (let i = 0; i < models.length; i++) {
        const model = models[i];
        try {
          chosenModelIndex = i;
          const apiKeyStream = Deno.env.get('OPENROUTER_API_KEY');
          if (!apiKeyStream) {
            throw new Error('OPENROUTER_API_KEY not set');
          }
          if (isGrokModel(model)) {
            const grokFetchStart = Date.now();
            const grokAbort = new AbortController();
            const grokTimeoutId = setTimeout(() => grokAbort.abort(), 60000);
            let res: Response;
            try {
              res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
                method: 'POST',
                headers: {
                  'Authorization': `Bearer ${apiKeyStream}`,
                  'Content-Type': 'application/json',
                  'HTTP-Referer': 'https://momma-stock-insight.vercel.app',
                  'X-Title': 'momma-manual'
                },
                body: JSON.stringify({
                  model,
                  messages: [ { role: 'system', content: SYSTEM_PROMPT }, { role: 'user', content: prompt } ],
                  temperature: 0.1,
                  response_format: { type: 'json_object' }
                }),
                signal: grokAbort.signal
              });
            } finally {
              clearTimeout(grokTimeoutId);
            }
            if (!res.ok) {
              const txt = await res.text().catch(() => '');
              logEvent('warning', 'fallback_model_fail', { model, status: res.status, errorText: txt });
              throw new Error(`Falha request ${model}: ${res.status} ${txt}`);
            }
            const data = await res.json();
            const grokDurationMs = Date.now() - grokFetchStart;
            const content = data?.choices?.[0]?.message?.content ?? '';
            logEvent('info', 'openrouter_response', { model, contentLength: content.length, content });
            // Record telemetry metrics for Grok non-streaming response
            if (metrics && data?.usage) {
              const grokInputTokens = data.usage.prompt_tokens ?? 0;
              const grokOutputTokens = data.usage.completion_tokens ?? 0;
              metrics.recordLlmCall({
                model: data.model || model,
                provider: 'openrouter',
                operation: 'requisition-parse',
                inputTokens: grokInputTokens,
                outputTokens: grokOutputTokens,
                durationMs: grokDurationMs,
              });
            }
            let parsedResponse = null;
            try {
              let clean = content.trim();
              if (clean.startsWith('```')) {
                clean = clean.replace(/^```(?:json)?\s*/, '').replace(/\s*```$/, '');
              }
              parsedResponse = JSON.parse(clean);
            } catch {
              sendEvent('error', { message: 'Erro ao processar resposta da IA' });
              logEvent('error', 'parse_error', { model, content });
              throw new Error('Erro ao processar resposta da IA');
            }
            try {
              const categories = Array.isArray(parsedResponse?.categories) ? parsedResponse.categories : [];
              if (categories.length > 0) {
